# UARD (Untrapped Auto-Repair Diagnostic) ver 1.0.0 - TRUE BASELINE
# UARD repairs and updates only Untrapped-owned components. Baseline 1.0.0 may only be retained or upgraded.
$ErrorActionPreference='Stop'
$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.0';$UARDTitle="$UARDName ver $UARDVersion"
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$ExtensionRoot=Split-Path -Parent $Root;$RepoBase='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/';$BackupRoot=Join-Path $Root 'repair-backups';$RepairReport=Join-Path $Root 'repair-success-latest.txt';$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$log=New-Object 'System.Collections.Generic.List[string]';$changed=$false;$failed=$false;$verificationUnknown=$false;$normalizationAttempted=$false;$normalizationSucceeded=$false;$normalizationFailed=$false;$normalizationFiles=New-Object 'System.Collections.Generic.List[string]';$attempts=4
function Log([string]$s){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$s;Write-Host $x -ForegroundColor Gray;[void]$log.Add($x)}
function Hash([byte[]]$b){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function VersionOf([byte[]]$b){try{$t=[Text.Encoding]::UTF8.GetString($b);$m=[regex]::Match($t,'(?im)^(?:#|//).*?ver(?:sion)?\s+([0-9]+(?:\.[0-9]+){2})');if($m.Success){return [version]$m.Groups[1].Value}}catch{};return [version]'0.0.0'}
function Normalize([byte[]]$b,[string]$name){try{$t=[Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF).Trim();if($t.StartsWith('{') -or $t.StartsWith('[')){$j=$null;try{$j=$t|ConvertFrom-Json -ErrorAction Stop}catch{return $b};$v=$null;foreach($k in @('content','script','powershell','text','source')){if($j.PSObject.Properties.Name -contains $k){$v=[string]$j.$k;break}};if($null -ne $v){$script:normalizationAttempted=$true;if($j.PSObject.Properties.Name -contains 'encoding' -and [string]$j.encoding -eq 'base64'){$o=[Convert]::FromBase64String($v)}elseif($j.PSObject.Properties.Name -contains 'content_encoding' -and [string]$j.content_encoding -eq 'base64'){$o=[Convert]::FromBase64String($v)}else{$o=[Text.Encoding]::UTF8.GetBytes($v)};$script:normalizationSucceeded=$true;[void]$script:normalizationFiles.Add($name);Log ('NORMALIZE SUCCESS '+$name+' JSON source wrapper translated to native artifact.');return $o}}};return $b}catch{$script:normalizationAttempted=$true;$script:normalizationFailed=$true;Log ('NORMALIZE FAILED '+$name+': '+$_.Exception.Message);return $b}}
function Valid([hashtable]$x,[byte[]]$b){try{if($b.Length -lt 20){throw 'File is unexpectedly small.'};if($x.Type -eq 'script'){[void][scriptblock]::Create([Text.Encoding]::UTF8.GetString($b))}elseif($x.Type -eq 'json'){$null=([Text.Encoding]::UTF8.GetString($b)|ConvertFrom-Json)}elseif($x.Type -eq 'js'){if(([Text.Encoding]::UTF8.GetString($b)).Length -lt 20){throw 'JavaScript file is unexpectedly small.'}};return $true}catch{return $false}}
function Download([hashtable]$x){$url=$RepoBase+$x.Remote+'?cb='+[DateTime]::UtcNow.Ticks;Log ('DOWNLOAD START '+$x.Remote);$r=Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop;if($x.Type -eq 'binary'){$ms=New-Object IO.MemoryStream;$r.RawContentStream.CopyTo($ms);$b=$ms.ToArray();$ms.Dispose()}else{$b=[Text.Encoding]::UTF8.GetBytes([string]$r.Content)};$b=Normalize $b $x.Remote;if(-not(Valid $x $b)){throw ('Canonical validation failed after normalization: '+$x.Remote)};Log ('DOWNLOAD OK '+$x.Remote+' ('+$b.Length+' bytes)');return $b}
function RepairOne([string]$base,[hashtable]$x,[string]$label){$path=Join-Path $base $x.Rel;Log ('CHECK '+$label+'/'+$x.Rel);$remote=$null;$tmp=$null;for($i=1;$i -le $attempts;$i++){try{$remote=Download $x;break}catch{$err=$_.Exception.Message;Log ('RETRY '+$x.Remote+' attempt '+$i+'/'+$attempts+': '+$err);if($i -lt $attempts){Start-Sleep -Seconds 2}}};if($null -eq $remote){Log ('UNVERIFIED '+$label+'/'+$x.Rel+' canonical source unavailable; no repair failure established.');$script:verificationUnknown=$true;return};$same=$false;if(Test-Path -LiteralPath $path){try{$same=(Hash ([IO.File]::ReadAllBytes($path))) -eq (Hash $remote)}catch{}};if($same){Log ('CURRENT '+$label+'/'+$x.Rel);return};Log ('UPDATE NEEDED '+$label+'/'+$x.Rel);try{if(-not(Test-Path $BackupRoot)){New-Item -ItemType Directory -Path $BackupRoot -Force|Out-Null};if(Test-Path $path){$backup=Join-Path $BackupRoot ($stamp+'-'+$label.Replace('/','_')+'-'+$x.Rel.Replace('/','_'));Copy-Item $path $backup -Force;Log ('BACKUP '+$backup)};$parent=Split-Path $path -Parent;if(-not(Test-Path $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$tmp=$path+'.repair-'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllBytes($tmp,$remote);$tb=[IO.File]::ReadAllBytes($tmp);if((Hash $tb) -ne (Hash $remote)){throw 'Temporary SHA-256 verification failed.'};if(-not(Valid $x $tb)){throw 'Temporary validation failed.'};Move-Item $tmp $path -Force;$tmp=$null;$pb=[IO.File]::ReadAllBytes($path);if((Hash $pb) -ne (Hash $remote)){throw 'Post-write SHA-256 verification failed.'};Log ('REPAIRED+VERIFIED '+$label+'/'+$x.Rel);$script:changed=$true}catch{$script:failed=$true;Log ('FAIL '+$label+'/'+$x.Rel+': '+$_.Exception.Message);if($tmp){Remove-Item $tmp -Force -ErrorAction SilentlyContinue}}}
function FindBraveUntrapped{$out=@();$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(Test-Path $ud){foreach($p in @(Get-ChildItem $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -eq 'Default' -or $_.Name -like 'Profile *'})){foreach($v in @(Get-ChildItem (Join-Path $p.FullName 'Extensions') -Directory -Recurse -ErrorAction SilentlyContinue)){foreach($ver in @(Get-ChildItem $v.FullName -Directory -ErrorAction SilentlyContinue)){$m=Join-Path $ver.FullName 'manifest.json';if(Test-Path $m){try{if(([string](Get-Content $m -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$ver.FullName}}catch{}}}}}};foreach($proc in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.Name -match '^brave' -and $_.CommandLine -match '(?i)--load-extension='})){foreach($arg in ([regex]::Matches($proc.CommandLine,'--load-extension=([^\s"]+)'))){$d=$arg.Groups[1].Value;$m=Join-Path $d 'manifest.json';if(Test-Path $m){try{if(([string](Get-Content $m -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$d}}catch{}}}};@($out|Sort-Object -Unique)}
function RestartOwnedProcesses{Log 'RESTART Checking Untrapped-owned processes.';$found=$false;foreach($pat in @('*packet-filter.ps1*','*ultra-mode.ps1*')){@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like $pat})|ForEach-Object{Log ('STOP PID '+$_.ProcessId);Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue;$found=$true}};if($found){Start-Sleep -Milliseconds 800};foreach($f in @('packet-filter.ps1','ultra-mode.ps1')){$p=Join-Path $Root $f;if(Test-Path $p){Log ('START '+$f);Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$p) -WorkingDirectory $Root -Verb RunAs -WindowStyle Hidden -ErrorAction SilentlyContinue}};Log 'RESTART COMPLETE'}
$Core=@(@{Remote='ultra-mode/INSTALL-PACKET-FILTER.ps1';Rel='INSTALL-PACKET-FILTER.ps1';Type='script'},@{Remote='ultra-mode/INSTALL-ULTRA-MODE.ps1';Rel='INSTALL-ULTRA-MODE.ps1';Type='script'},@{Remote='ultra-mode/config.json';Rel='config.json';Type='json'},@{Remote='ultra-mode/create-override.ps1';Rel='create-override.ps1';Type='script'},@{Remote='ultra-mode/generate-keys.ps1';Rel='generate-keys.ps1';Type='script'},@{Remote='ultra-mode/packet-filter.ps1';Rel='packet-filter.ps1';Type='script'},@{Remote='ultra-mode/self-repair.ps1';Rel='self-repair.ps1';Type='script'},@{Remote='ultra-mode/status-untrapped.ps1';Rel='status-untrapped.ps1';Type='script'},@{Remote='ultra-mode/test-untrapped.ps1';Rel='test-untrapped.ps1';Type='script'},@{Remote='ultra-mode/ultra-mode.ps1';Rel='ultra-mode.ps1';Type='script'},@{Remote='ultra-mode/verify-override.ps1';Rel='verify-override.ps1';Type='script'})
$Ext=@(@{Remote='manifest.json';Rel='manifest.json';Type='json'},@{Remote='background.js';Rel='background.js';Type='js'},@{Remote='content.js';Rel='content.js';Type='js'},@{Remote='popup.html';Rel='popup.html';Type='text'},@{Remote='popup.js';Rel='popup.js';Type='js'},@{Remote='bootstrap.bundle.min.js';Rel='bootstrap.bundle.min.js';Type='js'},@{Remote='assets/untrapped.png';Rel='assets/untrapped.png';Type='binary'},@{Remote='assets/untrapped.svg';Rel='assets/untrapped.svg';Type='binary'})
try{[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;Log "=== $UARDTitle SELF-REPAIR BEGIN ===";Log 'BASELINE: TRUE BASELINE ver 1.0.0 retained; this run may only repair/build upon it.';Log 'DIAGNOSIS: Checking every Untrapped-owned operational component.';foreach($x in $Ext){RepairOne $ExtensionRoot $x 'extension-source'};foreach($x in $Core){RepairOne $Root $x 'ultra-mode'};Log 'BRAVE: Checking packaged and developer-loaded copies.';$matches=FindBraveUntrapped;Log ('BRAVE: Untrapped copies found: '+$matches.Count);foreach($m in $matches){foreach($x in $Ext){RepairOne $m $x 'brave-extension'}};foreach($native in @('WinDivert.dll','WinDivert64.sys')){if(Test-Path (Join-Path $Root $native)){Log ('NATIVE OK '+$native)}else{$failed=$true;Log ('FAIL MISSING '+$native)}};if($normalizationAttempted){if($normalizationFailed){Log 'NORMALIZATION RESULT: UNSUCCESSFUL'}elseif($normalizationSucceeded){Log ('NORMALIZATION RESULT: SUCCESSFUL - '+$normalizationFiles.Count+' artifact(s) normalized: '+($normalizationFiles -join ', '))}else{Log 'NORMALIZATION RESULT: NOT NEEDED'}}else{Log 'NORMALIZATION RESULT: NOT NEEDED - no JSON wrapper encountered.'};if($changed){RestartOwnedProcesses}else{Log 'RESTART: NOT NEEDED'};if($failed){$diag='REPAIR INCOMPLETE'}elseif($verificationUnknown){$diag='VERIFICATION INCOMPLETE'}elseif($changed){$diag='REPAIR SUCCESS'}else{$diag='NO REPAIR REQUIRED'};[void]$log.Add('');[void]$log.Add('[DIAGNOSIS] '+$diag);[void]$log.Add('IDENTITY: '+$UARDTitle);[void]$log.Add('VERSION: '+$UARDVersion);[void]$log.Add('TRUE BASELINE: 1.0.0 - RETAINED/UPGRADED, NEVER REMOVED');if($normalizationFailed){$normResult='UNSUCCESSFUL'}elseif($normalizationSucceeded){$normResult='SUCCESSFUL'}else{$normResult='NOT NEEDED'};[void]$log.Add('NORMALIZATION: '+$normResult);[void]$log.Add('FAILURE THRESHOLD: only actual repair failure or missing required native component is REPAIR INCOMPLETE.');[void]$log.Add('PROTECTED: Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy are never modified.');$log|Set-Content $RepairReport -Encoding UTF8;Log '=== UARD SELF-REPAIR END ===';if($changed -or $failed){Start-Process notepad.exe -ArgumentList @($RepairReport) -ErrorAction SilentlyContinue};if($failed){exit 1}elseif($verificationUnknown){exit 2}else{exit 0}}catch{Log ('FAIL FATAL '+$_.Exception.Message);@($UARDTitle,'UARD FAILURE','[DIAGNOSIS] '+$_.Exception.Message,'TRUE BASELINE: 1.0.0')|Set-Content $RepairReport -Encoding UTF8;Start-Process notepad.exe -ArgumentList @($RepairReport) -ErrorAction SilentlyContinue;exit 1}